/* 生平大事记 第十七批：清·下（4人） */

Object.assign(PEOPLE_TIMELINE, {

  "hulinyi": [
    ["1812", "湖南益阳人，陶澍之婿。道光进士。"],
    ["1854-1855", "湘军初创期独领一军，转战湖北；武昌三克三失，终定之——湖北遂为湘军粮台根本。"],
    ["1856", "「处处筹饷，支撑东南大局」；困守南昌数月。"],
    ["1861", "安庆战役方酣，呕血死于武昌，四十九岁。曾左之外，湘军第三人；时论「润帅之才在曾左之间」。"]
  ],


});
Object.assign(PEOPLE_TIMELINE, {
  "liumingchuan": [
    ["1836", "安徽合肥人。团练起家，淮军「铭字营」营官。"],
    ["1862-1865", "随李鸿章援上海、平苏南，铭字营为淮军之冠。"],
    ["1865/1868", "捻军之役：尹隆河、徒骇河，东捻西捻皆铭军与诸军合力平之。"],
    ["1884", "督办台湾军务，淡水之战挫法舰——「保台第一功」。"],
    ["1885-1891", "台湾建省首任巡抚：修基隆—台北铁路（中国自建第一条客运铁路）、架电线、办西学堂、清赋——「以一隅之设施为全国之范」。"],
    ["1896", "闻《马关条约》割台，忧愤而卒。"]
  ],
  "guosongtao": [
    ["1818", "湖南湘阴人。与曾国藩刘蓉为友，劝曾出山办团练者即其人。"],
    ["1856-1860", "入值南书房，僧格林沁天津之役的旁观者。"],
    ["1876", "出使英国钦差大臣——中国第一任驻外公使。「郭筠仙瞪眼看世界，全国人已骂他汉奸」。"],
    ["1877", "《使西纪程》盛言西洋政教修明，奉旨毁版；副使刘锡鸿逐日诋之。"],
    ["1879-1891", "归国，「第一骂名」随身至死。三十年后其言尽验——孤独的先知。"]
  ],
  "ronghong": [
    ["1828", "生于广东香山南屏贫家。入澳门马礼逊学堂。"],
    ["1847-1855", "随布朗校长赴美，1850年入耶鲁——中国近代第一位美国一流大学毕业生。"],
    ["1855-1863", "归国历事多途，「以西方之学术灌输于中国」之志不坠。"],
    ["1863-1865", "为曾国藩赴美购机器——江南制造总局之始。"],
    ["1872-1875", "主持幼童留美四批一百二十人：詹天佑、唐绍仪、梁敦彦皆出其中——「中国留学生之父」。"],
    ["1900-1912", "参与维新与革命；1912年病逝美国，终未能亲见民国。"]
  ]
});

